	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		Aircraft
	 */
		public Aircraft createAircraft( CreateAircraftCommand command ) {

		Aircraft entity = new Aircraft();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setAircraftId( command.getAircraftId() );
            entity.setMsn( command.getMsn() );
            entity.setDeliveryDate( command.getDeliveryDate() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of Aircraft {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateAircraftCommand
	 * @return		Aircraft
	 */
	public Aircraft updateAircraft( UpdateAircraftCommand command ) {

		Aircraft entity = new Aircraft();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setAircraftId( command.getAircraftId() );
            entity.setMsn( command.getMsn() );
            entity.setDeliveryDate( command.getDeliveryDate() );
            entity.setVariant( command.getVariant() );
            entity.setOperator( command.getOperator() );
            entity.setRegistration( command.getRegistration() );
            entity.setWarranty( command.getWarranty() );
            entity.setMaintenanceRecords( command.getMaintenanceRecords() );
            entity.setConnectedAircraft( command.getConnectedAircraft() );
            entity.setCabinLayout( command.getCabinLayout() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of Aircraft {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteAircraftCommand
	 */
	public void delete( DeleteAircraftCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getAircraftId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of Aircraft {0} ", id );

	}

	/**
	 * Method to retrieve the Aircraft via AircraftFetchOneSummary
	 * @param 	summary AircraftFetchOneSummary
	 * @return 	AircraftFetchOneResponse
	 */
	public Aircraft getAircraft( AircraftFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "AircraftFetchOneSummary arg cannot be null" );

		Aircraft entity = null;
		UUID id = summary.getAircraftId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a Aircraft using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all Aircrafts
	 *
	 * @return 	List<Aircraft>
	 */
    public List<Aircraft> getAllAircraft() {
		List<Aircraft> list = projector.findAll( new FindAllAircraftQuery() );
		return list;
	}

